  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C05", "C31", "C32", "C34", "C36", "C38", "C44", "C07", "C15", "C20"],
  "claims": [
    {
      "claim": "The query is a difunctional glycidyl ether with two oxirane rings that can directly haptenate skin proteins. L3 MIE records show glycidyl ethers and epoxides covalently bind proteins: phenyl glycidyl ether adducted HSA at Cys34, Cys62 and Lys190 (C34), butyl glycidyl ether depleted cell-surface thiols in THP-1 cells (C38), and propylene oxide formed hemoglobin adducts in vivo (C36).",
      "card_ids": ["C34", "C38", "C36"]
    },
    {
      "claim": "Resorcinol diglycidyl ether, a diglycidyl ether structurally analogous to the query, conjugated with glutathione in vitro (C44), directly supporting the query's molecular initiating event.",
      "card_ids": ["C44"]
    },
    {
      "claim": "A cycloaliphatic diepoxide showed positive peptide depletion, confirming that diepoxide scaffolds react with protein nucleophiles even when reactivity is low (C40). Styrene oxide and trichloropropene oxide also depleted GSH (C41, C42).",
      "card_ids": ["C40", "C41", "C42"]
    },
    {
      "claim": "An LLNA study of an epoxide-containing compound reported weak sensitization with EC3 of 3.4 M (C05, C31, C32), providing in vivo evidence that epoxide electrophiles induce skin sensitization.",
      "card_ids": ["C05", "C31", "C32"]
    },
    {
      "claim": "Human patch tests and guinea pig tests on multifunctional reactive crosslinkers DPGDA and TPGDA were positive (C07, C08, C15, C20, C29), consistent with the query's difunctional electrophilic structure.",
      "card_ids": ["C07", "C08", "C15", "C20", "C29"]
    },
    {
      "claim": "The KeratinoSens positive result for Tween 80 (C35) is an explicitly identified false positive from oxidative stress and is not applicable to the query. No transferable negative sensitization evidence for the query or a close diepoxide analog was provided.",
      "card_ids": ["C35"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "sensitization_aop",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C34", "C36", "C38", "C40", "C41", "C42", "C44"]
    },
    {
      "family": "sensitization_aop",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C35"]
    }
  ],
  "evidence_gaps": [
    "No direct human or in vivo sensitization test on the query molecule itself was provided.",
    "No validated negative sensitization result for the query or a close diepoxide analog was provided.",
    "L3 records are mechanistic AOP events, not independent gold votes for the binary label.",
    "Skin exposure context is unclear; low logP may limit permeation, but permeability is exposure context and not endpoint proof."
  ],
  "decision_summary": "The query is a difunctional glycidyl ether (diepoxide) capable of direct covalent haptenation. L3 AOP evidence shows that glycidyl ethers and epoxides bind skin proteins (C34, C36, C38, C41, C42) and that a diglycidyl ether conjugates glutathione (C44), coherently supporting the sensitization MIE. L1 evidence adds an LLNA-positive epoxide (C05, C31, C32) and positive human and guinea pig outcomes for multifunctional reactive crosslinkers (C07, C08, C15, C20, C29). No transferable negative evidence exists. Skin sensitization risk is predicted with high confidence."
}

